WITH mun AS (SELECT * FROM UNNEST(['2930766','2918100','2900355','2929701','2926509','2909208']) AS id_municipio),car AS (SELECT REPLACE(id_imovel,'-','') id_car_norm,id_imovel,id_municipio,area FROM `basedosdados.br_sfb_sicar.area_imovel` JOIN mun USING(id_municipio) WHERE data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(id_imovel,'-','') ORDER BY data_extracao DESC)=1),p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2013 AND 2026 AND id_car IS NOT NULL AND TRIM(id_car)!=''),n AS (SELECT ano_emissao,id_referencia_bacen,numero_ordem,COUNT(*) n_imoveis FROM p GROUP BY 1,2,3),b AS (SELECT c.id_municipio,c.id_imovel,op.id_referencia_bacen,e.produto,e.finalidade,op.valor_parcela_credito/n.n_imoveis credito FROM p JOIN n USING(ano_emissao,id_referencia_bacen,numero_ordem) JOIN `basedosdados.br_bcb_sicor.operacao` op USING(ano_emissao,id_referencia_bacen,numero_ordem) JOIN car c USING(id_car_norm) LEFT JOIN `basedosdados.br_bcb_sicor.empreendimento` e USING(id_empreendimento) WHERE op.ano_emissao BETWEEN 2013 AND 2026 AND c.area<0.1),r AS (SELECT id_municipio,COALESCE(produto,'(sem produto)') produto,COALESCE(finalidade,'(sem finalidade)') finalidade,COUNT(DISTINCT id_referencia_bacen) operacoes,COUNT(DISTINCT id_imovel) imoveis,SUM(credito) credito,ROW_NUMBER() OVER(PARTITION BY id_municipio ORDER BY SUM(credito) DESC) rn FROM b GROUP BY 1,2,3) SELECT * FROM r WHERE rn<=10 ORDER BY id_municipio,rn